#pragma once

#include "engine/core/ecs/entity.h"

#include <memory>
#include <string>
#include <string_view>
#include <vector>

namespace sfs
{

class GameObject;
class MeshLibrary;
class Scene;
class System;

/**
 * How to instantiate a game's scripts: the systems, game objects and mesh
 * sources a game module declares. Generated by sfs-codegen alongside the module's reflection
 * and consulted when a scene starts playing.
 */
struct ScriptType
{
  enum class Kind
  {
    System,
    GameObject,
    MeshSource,
  };

  std::string name;   // C++ class name, e.g. "Player"
  std::string module; // which module registered it
  Kind kind = Kind::GameObject;

  // Kind::System: add a default-constructed instance to the scene.
  System& (*addSystem)(Scene& scene) = nullptr;

  // Kind::GameObject: a new, unattached instance (Scene::adoptObject binds it).
  std::unique_ptr<GameObject> (*createObject)() = nullptr;

  // Kind::MeshSource: add its meshes to a scene's mesh library.
  void (*buildMeshes)(MeshLibrary& library) = nullptr;
};

/**
 * Every script type from every loaded game module. One instance per process
 * (it lives in the engine library), like reflect::types().
 */
class ScriptRegistry
{
public:
  /** Add a script type (replacing any with the same name). */
  void add(ScriptType type);

  /** Drop every script type a module registered, e.g. before unloading it. */
  void removeModule(std::string_view module);

  const ScriptType* find(std::string_view name) const;

  const std::vector<ScriptType>& types() const { return m_types; }

private:
  std::vector<ScriptType> m_types;
};

/** The process-wide script registry. */
ScriptRegistry& scripts();

/**
 * Start a scene's scripts: add the named game systems, and attach a game
 * object to every entity with a ScriptComponent, its fields set from the
 * component's saved values before its onCreate runs. Unknown names are logged
 * and skipped.
 *
 * @param meshes resolves mesh-valued script fields (may be null)
 */
void startScripts(Scene& scene,
                  const std::vector<std::string>& systems,
                  MeshLibrary* meshes = nullptr);

} // namespace sfs
